async function readFolder(kind) {
  const files = api && api.files;
  if (!files || !files.requestFolder) return { error: kind === "claude-design" ? "Folder access needs a newer Hermes. Pick the .zip instead." : "Folder access needs a newer Hermes. Pick the package’s tokens.css file instead.", fallback: true };
  const picked = await files.requestFolder();
  if (!picked.ok) return { error: picked.message || "Imprint could not open that folder." };
  if (!picked.folder) return { cancelled: true };
  const id = picked.folder.id;
  const out = {};
  const text = async (path) => {
    const r = await files.readText(id, path);
    if (r.ok) out[path] = r.text;
  };
  const data = async (path) => {
    const r = await files.readDataUrl(id, path);
    if (r.ok) out[path] = r.url;
  };
  const list = async (path) => {
    const r = await files.list(id, path);
    return r.ok ? r.entries : [];
  };
  const find = (entries, name, dir) => entries.find((e) => !!e.isDirectory === !!dir && e.name.toLowerCase() === name);
  try {
    let root = await list("");
    if (kind === "open-design") {
      for (const n of ["manifest.json", "tokens.css", "design.md", "design-tokens.json"]) {
        const e = find(root, n);
        if (e) await text(e.path);
      }
    } else {
      const proj = find(root, "project", true);
      if (proj) root = await list(proj.path);
      for (const n of ["design-system.json", "tokens.json", "tokens.css"]) {
        const e = find(root, n);
        if (e) await text(e.path);
      }
      const fonts = find(root, "fonts", true);
      if (fonts) for (const e of (await list(fonts.path)).filter((e2) => !e2.isDirectory && /\.(ttf|otf|woff2?)$/i.test(e2.name)).slice(0, 8)) await data(e.path);
      const assets = find(root, "assets", true);
      if (assets) for (const d of (await list(assets.path)).filter((e) => e.isDirectory && /logo/i.test(e.name)).slice(0, 3)) {
        for (const e of (await list(d.path)).filter((e2) => !e2.isDirectory && /\.(svg|png)$/i.test(e2.name)).slice(0, 4)) await data(e.path);
      }
    }
  } finally {
    try {
      await files.release(id);
    } catch (e) {
    }
  }
  return { files: out };
}
