        h3("td", null, plural4(s.units, s.unit_label.replace(/s$/, ""))),
        h3("td", null, bytes(s.bytes || s.chars)),
        h3("td", null, h3(DeleteButton, { size: "sm", onDelete: () => removeSource(s.id) }))
